UPDATE linkable_cards
SET is_linked = 1
WHERE id = #{linkableCardId}

UPDATE cards
SET is_deleted = 0, deleted_at = NULL, is_primary = #{isPrimary}, updated_at = NOW(),
card_company_code = #{cardCompanyCode}, card_name = #{cardName},
card_classification = #{cardClassification}, card_type = #{cardType}
WHERE id = #{cardId} AND user_id = #{userId}

UPDATE cards
SET is_primary = 1
WHERE id = #{cardId} AND user_id = #{userId}

UPDATE cards
SET card_name = #{cardNickname}, updated_at = NOW()
WHERE id = #{cardId} AND user_id = #{userId}

UPDATE cards
SET is_deleted = 1, deleted_at = NOW()
WHERE id = #{cardId} AND user_id = #{userId}
